/* three.js, vendored in rouh/static/three/ and resolved by the page's import
   map (rouh/web/assets.py, `_three`). Only the 3D orb (app/orb3d.js) loads it,
   and only after it has checked that this browser can draw in WebGL. Its own
   types are not vendored, so it is checked as `any`. */
declare module 'three';
declare module 'three/addons/*';
